INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT156-S4-Q2$batch08$, 156, 4, 2, $batch08$Most Strongly Supported$batch08$, $batch08$The relationship between money and the things it allows one to purchase is like that between a tool and the tasks it enables its user to accomplish. Therefore, since tools are useless if there is no task that needs to be done, _______.$batch08$, $batch08$Which one of the following most logically completes the argument?$batch08$, $batch08$C$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q2$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$money should be thought of as no more useful than a tool$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$any tool that enables its user to accomplish a task is valuable$batch08$, $batch08$Reversed$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$money is valueless in a world where nothing is for sale$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$money should be regarded as a tool rather than a commodity$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$the value of money derives from the tasks it allows one to accomplish$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Money is to the things it buys as a tool is to the tasks it does. Tools are useless if there's no task to do.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Finish the analogy by swapping terms. Tool → money. Task → something to buy. "Tools are useless if there is no task" becomes "money is useless if there is nothing to buy".$batch08$), (2, $batch08$Goal$batch08$, $batch08$Money has no value if there is nothing to buy.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$The analogy compares relationships. It doesn't rank money's usefulness against tools.$batch08$), ($batch08$B$batch08$, $batch08$The premise says a tool with no task is useless. B claims that a tool *with* a task is valuable. That doesn't follow.$batch08$), ($batch08$C$batch08$, $batch08$Swap the terms into "tools are useless if there is no task" and you get C.$batch08$), ($batch08$D$batch08$, $batch08$The passage doesn't classify money as a tool or a commodity. It only compares the two relationships.$batch08$), ($batch08$E$batch08$, $batch08$This mixes the two halves of the analogy: tasks belong to tools, purchases to money. And "derives from" is a stronger claim than the passage makes.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT156-S4-Q2$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
